def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr in range(rr-1, rr+2):
                    for nc in range(cc-1, cc+2):
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr,nc) not in seen:
                            seen.add((nr,nc))
                            stack.append((nr,nc))
            r0, r1 = min(x[0] for x in cells), max(x[0] for x in cells)
            c0, c1 = min(x[1] for x in cells), max(x[1] for x in cells)
            shape = [[grid[rr][cc] for cc in range(c0,c1+1)] for rr in range(r0,r1+1)]
            objects.append((r0, c0, shape))
    row_spread = max(r + len(shape)/2 for r, c, shape in objects) - min(r + len(shape)/2 for r, c, shape in objects)
    col_spread = max(c + len(shape[0])/2 for r, c, shape in objects) - min(c + len(shape[0])/2 for r, c, shape in objects)
    if col_spread >= row_spread:
        objects.sort(key=lambda item: item[1])
        out = [[0] * sum(len(shape[0]) for _, _, shape in objects) for _ in range(max(len(shape) for _, _, shape in objects))]
        offset = 0
        for _, _, shape in objects:
            for rr, row in enumerate(shape):
                for cc, value in enumerate(row):
                    out[rr][offset+cc] = value
            offset += len(shape[0])
    else:
        objects.sort(key=lambda item: item[0])
        out = []
        width = max(len(shape[0]) for _, _, shape in objects)
        for _, _, shape in objects:
            out.extend([row[:] for row in shape])
    return out
